"""Native exact polyline and waypoint-interpolating cubic construction.

``construct`` accepts the existing node helper, one ordered open POLY spline,
a scalar interpolation degree (0 or 3), physical width/offset and its two
directed endpoint tangents. It returns geometry plus a scalar validity socket.
No authored control is removed. Degree 3 uses aligned FREE Bezier handles:
the left handle length is the previous chord/3 and the right handle length is
the next chord/3. Both sides share the unit tangent T_i. Dividing each segment's
local derivative by its chord length gives T_i at both sides of the knot, so
the centerline is C1 under a cumulative chord-length parameter. A short adjacent
chord does not shrink the handle on a long span. All knots are interpolated.

The smooth-mode guard bounds curvature continuously over each of 64 intervals
per cubic. Quadratic velocity Bernstein controls give a positive projected
speed lower bound; cubic coefficients of velocity cross acceleration give a
norm upper bound. Their ratio bounds curvature over the entire interval, not
merely at sampled points. The full pavement reach must stay below 98 percent
of the corresponding curvature radius. Global overlap remains a separate test.
"""

CURVATURE_INTERVALS = 64
EVALUATION_RESOLUTION = 256
OFFSET_JACOBIAN_MARGIN = .02


def weighted_retry_group():
    """Keep the alternative certificate in a small reusable native group.

    A group boundary prevents repeating the caller's large mouth/trim field
    dependency graph inside the second continuous curvature certificate.
    """
    import bpy
    from .path_surface_nodes import _Nodes
    name='Prochitecture Streets / Spacing weighted cubic retry v1'
    existing=bpy.data.node_groups.get(name)
    if existing:return existing
    tree=bpy.data.node_groups.new(name,'GeometryNodeTree');g=_Nodes(tree)
    for name,kind in (('Polyline','NodeSocketGeometry'),('Width','NodeSocketFloat'),('Offset','NodeSocketFloat'),
        ('Start Tangent','NodeSocketVector'),('End Tangent','NodeSocketVector')):
        tree.interface.new_socket(name=name,in_out='INPUT',socket_type=kind)
    tree.interface.new_socket(name='Curve',in_out='OUTPUT',socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Valid',in_out='OUTPUT',socket_type='NodeSocketBool')
    inp=g.node('NodeGroupInput','Original trimmed controls and dimensional envelope')
    out=g.node('NodeGroupOutput','Certified alternative interpolating cubic')
    curve,valid=construct(g,inp.outputs['Polyline'],3,inp.outputs['Width'],inp.outputs['Offset'],
        (inp.outputs['Start Tangent'],inp.outputs['End Tangent']),weighted_tangents=True)
    g.set(curve,out.inputs['Curve']);g.set(valid,out.inputs['Valid'])
    return tree


def construct(g, polyline, degree, width, offset, endpoint_tangents, *, reach_bound=None, weighted_tangents=False):
    """Return ``(curve, valid)`` without replacing invalid input by a fillet.

Named POINT fields retained on both output representations:
st_knot_index; st_curve_handle_left/right (absolute coordinates);
st_curve_tangent; st_curve_handle_length_left/right. These are transient GN geometry
attributes, never a replacement for the authored input vertices.
"""
    index = g.node('GeometryNodeInputIndex', 'Preserved waypoint index').outputs[0]
    position = g.node('GeometryNodeInputPosition', 'Authored trimmed waypoint').outputs[0]
    count = g.node('GeometryNodeAttributeDomainSize', 'Every authored waypoint remains a curve control')
    count.component = 'CURVE'
    g.set(polyline, count.inputs['Geometry'])
    n = count.outputs['Point Count']
    last = g.math('SUBTRACT', n, 1.)
    first = g.compare(index, 0, 'EQUAL', 'INT')
    final = g.compare(index, last, 'EQUAL', 'INT')
    previous = g.sample(polyline, position, g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.)), 'FLOAT_VECTOR')
    following = g.sample(polyline, position, g.math('MINIMUM', last, g.math('ADD', index, 1.)), 'FLOAT_VECTOR')
    incoming = g.vector('SUBTRACT', position, previous)
    outgoing = g.vector('SUBTRACT', following, position)
    before, after = g.vector('LENGTH', incoming), g.vector('LENGTH', outgoing)
    tangent_sum = g.vector('ADD', g.vector('NORMALIZE', incoming), g.vector('NORMALIZE', outgoing))
    if weighted_tangents:
        # An explicit candidate retry for irregularly spaced controls: let a
        # short chord influence the shared tangent more strongly, spreading
        # its turn into the longer neighboring span. Handle lengths stay
        # chord/3, all knots remain exact, endpoint tangents stay prescribed,
        # and the complete continuous curvature guard below still applies.
        tangent_sum=g.vector('ADD',
            g.vector('SCALE',g.vector('NORMALIZE',incoming),g.math('DIVIDE',1.,g.math('MAXIMUM',before,1e-8))),
            g.vector('SCALE',g.vector('NORMALIZE',outgoing),g.math('DIVIDE',1.,g.math('MAXIMUM',after,1e-8))))
    tangent = g.vector('NORMALIZE', tangent_sum)
    # Only disposable Bundle lead controls carry this field. Ordinary authored
    # cubic controls retain their established bisector tangent calculation.
    tangent = g.switch(g.named('st_curve_force_tangent', 'BOOLEAN'), tangent,
                       g.named('st_curve_forced_tangent', 'FLOAT_VECTOR'), 'VECTOR')
    tangent = g.switch(first, tangent, g.vector('NORMALIZE', endpoint_tangents[0]), 'VECTOR')
    tangent = g.switch(final, tangent, g.vector('NORMALIZE', endpoint_tangents[1]), 'VECTOR')
    # Each span sets its own derivative magnitude. Sharing the shorter of two
    # adjacent chord lengths creates an artificial near-stationary endpoint on
    # the longer span, and can turn a gentle editable bend into an offset cusp.
    # The two unused exterior handles use the terminal chord for completeness.
    left_length = g.math('DIVIDE', g.switch(first, before, after), 3.)
    right_length = g.math('DIVIDE', g.switch(final, after, before), 3.)
    left = g.vector('SUBTRACT', position, g.vector('SCALE', tangent, left_length))
    right = g.vector('ADD', position, g.vector('SCALE', tangent, right_length))
    recorded = polyline
    for name, value, kind in (
        ('st_knot_index', index, 'INT'),
        ('st_curve_handle_left', left, 'FLOAT_VECTOR'),
        ('st_curve_handle_right', right, 'FLOAT_VECTOR'),
        ('st_curve_tangent', tangent, 'FLOAT_VECTOR'),
        ('st_curve_handle_length_left', left_length, 'FLOAT'),
        ('st_curve_handle_length_right', right_length, 'FLOAT'),
    ):
        recorded = g.store(recorded, name, value, kind)

    convert = g.node('GeometryNodeCurveSplineType', 'Interpolate every waypoint with cubic Bezier segments')
    convert.spline_type = 'BEZIER'
    g.set(recorded, convert.inputs['Curve'])
    free = g.node('GeometryNodeCurveSetHandles', 'Explicit FREE handles retain the authored interpolation')
    free.mode = {'LEFT', 'RIGHT'}
    free.handle_type = 'FREE'
    g.set(convert.outputs['Curve'], free.inputs['Curve'])
    cubic = free.outputs['Curve']
    for side in ('LEFT', 'RIGHT'):
        handles = g.node('GeometryNodeSetCurveHandlePositions', side.title() + ' interpolating cubic handles')
        handles.mode = side
        g.set(cubic, handles.inputs['Curve'])
        g.set(g.named('st_curve_handle_' + side.lower(), 'FLOAT_VECTOR'), handles.inputs['Position'])
        cubic = handles.outputs['Curve']
    resolution = g.node('GeometryNodeSetSplineResolution', 'Accurate evaluated arc lengths between exact knots')
    resolution.inputs['Resolution'].default_value = EVALUATION_RESOLUTION
    g.set(cubic, resolution.inputs['Curve'])
    cubic = resolution.outputs['Curve']

    # Validate controls on the original polyline domain. Endpoint zero vectors
    # created by clamped neighbor lookup are intentionally excluded.
    legs_valid = g.all(
        g.either(first, g.compare(before, 1e-4, 'GREATER_THAN')),
        g.either(final, g.compare(after, 1e-4, 'GREATER_THAN')))
    common_valid = g.all(
        g.compare(n, 2, 'GREATER_EQUAL', 'INT'),
        g.compare(count.outputs['Spline Count'], 1, 'EQUAL', 'INT'),
        g.compare(width, 0., 'GREATER_THAN'),
        g.stat(polyline, legs_valid))
    tangent_valid = g.all(
        g.stat(polyline, g.compare(g.vector('LENGTH', tangent), .99, 'GREATER_THAN')),
        g.compare(g.vector('LENGTH', endpoint_tangents[0]), 1e-5, 'GREATER_THAN'),
        g.compare(g.vector('LENGTH', endpoint_tangents[1]), 1e-5, 'GREATER_THAN'))

    # One probe vertex represents a full parameter interval. Nothing is
    # approximated by requiring only pointwise curvature values to be small.
    intervals = g.node('GeometryNodeMeshLine', 'Bound every cubic on continuous parameter intervals')
    g.set(g.math('MULTIPLY', last, CURVATURE_INTERVALS), intervals.inputs['Count'])
    interval_geometry = intervals.outputs['Mesh']
    segment = g.math('FLOOR', g.math('DIVIDE', index, CURVATURE_INTERVALS))
    segment_next = g.math('ADD', segment, 1.)
    t0 = g.math('DIVIDE', g.math('MODULO', index, CURVATURE_INTERVALS), CURVATURE_INTERVALS)
    t1 = g.math('ADD', t0, 1. / CURVATURE_INTERVALS)
    tm = g.math('ADD', t0, .5 / CURVATURE_INTERVALS)

    def sample(value, at):
        return g.sample(recorded, value, at, 'FLOAT_VECTOR')

    p0 = sample(position, segment)
    p1 = sample(g.named('st_curve_handle_right', 'FLOAT_VECTOR'), segment)
    p2 = sample(g.named('st_curve_handle_left', 'FLOAT_VECTOR'), segment_next)
    p3 = sample(position, segment_next)
    a = g.vector('SUBTRACT', p1, p0)
    b = g.vector('SUBTRACT', p2, p1)
    c = g.vector('SUBTRACT', p3, p2)

    def scaled(value, scalar):
        return g.vector('SCALE', value, scalar)

    def add(*values):
        result = values[0]
        for value in values[1:]:
            result = g.vector('ADD', result, value)
        return result

    def velocity(t):
        complement = g.math('SUBTRACT', 1., t)
        return scaled(add(
            scaled(a, g.math('MULTIPLY', complement, complement)),
            scaled(b, g.math('MULTIPLY', 2., g.math('MULTIPLY', complement, t))),
            scaled(c, g.math('MULTIPLY', t, t))), 3.)

    def acceleration(t):
        return scaled(add(
            scaled(g.vector('SUBTRACT', b, a), g.math('SUBTRACT', 1., t)),
            scaled(g.vector('SUBTRACT', c, b), t)), 6.)

    acceleration0, acceleration1 = acceleration(t0), acceleration(t1)
    d0, d2 = velocity(t0), velocity(t1)
    d1 = add(d0, scaled(acceleration0, .5 / CURVATURE_INTERVALS))
    axis = g.vector('NORMALIZE', velocity(tm))
    speed_lower = g.math('MINIMUM', g.vector('DOT_PRODUCT', d0, axis),
                        g.math('MINIMUM', g.vector('DOT_PRODUCT', d1, axis), g.vector('DOT_PRODUCT', d2, axis)))
    cross = lambda x, y: g.vector('CROSS_PRODUCT', x, y)
    coefficients = (
        cross(d0, acceleration0),
        scaled(add(scaled(cross(d1, acceleration0), 2.), cross(d0, acceleration1)), 1. / 3.),
        scaled(add(cross(d2, acceleration0), scaled(cross(d1, acceleration1), 2.)), 1. / 3.),
        cross(d2, acceleration1),
    )
    numerator_upper = g.vector('LENGTH', coefficients[0])
    for coefficient in coefficients[1:]:
        numerator_upper = g.math('MAXIMUM', numerator_upper, g.vector('LENGTH', coefficient))
    curvature_upper = g.math('DIVIDE', numerator_upper,
                             g.math('POWER', g.math('MAXIMUM', speed_lower, 1e-8), 3.))
    reach = (g.math('ADD', g.math('ABSOLUTE', offset), g.math('MULTIPLY', width, .5))
             if reach_bound is None else reach_bound(recorded, segment))
    offset_valid = g.all(
        g.compare(speed_lower, 1e-5, 'GREATER_THAN'),
        g.compare(g.math('MULTIPLY', reach, curvature_upper), 1. - OFFSET_JACOBIAN_MARGIN, 'LESS_THAN'))
    smooth_valid = g.all(tangent_valid, g.stat(interval_geometry, offset_valid))
    exact = g.compare(degree, 0, 'EQUAL', 'INT')
    smooth = g.compare(degree, 3, 'EQUAL', 'INT')
    valid = g.all(common_valid, g.either(exact, smooth),
                  g.switch(smooth, True, smooth_valid, 'BOOLEAN', 'Smooth mode requires a regular offset curve'))
    curve = g.switch(smooth, recorded, cubic, 'GEOMETRY', 'Exact polyline or waypoint-interpolating cubic')
    return curve, valid
